def handle_type_a(item):
    value = item["value"] * 2
    return {
        "id": item["id"],
        "value": value,
        "category": "high" if value > 100 else "low"
    }

def handle_type_b(item):
    return {
        "id": item["id"],
        "value": item["value"] + 50,
        "category": "adjusted"
    }

def handle_type_c(item):
    is_negative = item["value"] < 0
    return {
        "id": item["id"],
        "value": 0 if is_negative else item["value"],
        "category": "clamped" if is_negative else "passthrough"
    }

STRATEGIES = {
    "A": handle_type_a,
    "B": handle_type_b,
    "C": handle_type_c,
}

def dispatch(item):
    handler = STRATEGIES.get(item.get("type"))
    return handler(item) if handler else None

def process_data(data):
    results = []
    for item in data:
        result = dispatch(item)
        if result is not None:
            results.append(result)
    return results
