/**
 * Represents the user's application settings
 */
export interface UserPreferences {
  theme: string;
  notifications: boolean;
  language: string;
}

/**
 * Represents the user profile schema
 */
export interface User {
  id: number;
  name: string;
  email: string;
  preferences: UserPreferences;
  tags: string[];
  last_login: string; // ISO 8601 format
  metadata: Record<string, any> | null;
}

/**
 * Runtime validation function for the User object
 * Uses a Type Guard to allow for type narrowing in TypeScript
 * 
 * @param data - The unknown data to validate
 * @returns boolean - True if data matches the User interface
 */
export function validateUser(data: any): data is User {
  if (typeof data !== 'object' || data === null) {
    return false;
  }

  // Validate primitive fields
  const hasValidPrimitives =
    typeof data.id === 'number' &&
    typeof data.name === 'string' && data.name.length > 0 &&
    typeof data.email === 'string' && data.email.includes('@') &&
    typeof data.last_login === 'string' && !isNaN(Date.parse(data.last_login));

  if (!hasValidPrimitives) return false;

  // Validate preferences sub-object
  const hasValidPreferences =
    data.preferences &&
    typeof data.preferences.theme === 'string' &&
    typeof data.preferences.notifications === 'boolean' &&
    typeof data.preferences.language === 'string';

  if (!hasValidPreferences) return false;

  // Validate tags array
  const hasValidTags =
    Array.isArray(data.tags) && 
    data.tags.every((tag: any) => typeof tag === 'string');

  if (!hasValidTags) return false;

  // Validate metadata (can be null or an object)
  const hasValidMetadata = 
    data.metadata === null || typeof data.metadata === 'object';

  if (!hasValidMetadata) return false;

  return true;
}

